file_ids = re.findall(r'file/d/([a-zA-Z0-9_-]+)', raw_text)
unique_ids = []
for fid in file_ids:
    if fid not in unique_ids:
        unique_ids.append(fid)

converted_data = []

for idx, fid in enumerate(unique_ids):
    item = {
        "index": idx + 1,
        "file_id": fid,
        "original_sharing_link": f"https://drive.google.com/file/d/{fid}/view?usp=sharing",
        "direct_view_link": f"https://drive.google.com/uc?export=view&id={fid}",
        "high_res_thumbnail_link": f"https://drive.google.com/thumbnail?id={fid}&sz=w800",
        "embed_iframe_link": f"https://drive.google.com/file/d/{fid}/preview",
        "img_tag": f'<img src="https://drive.google.com/thumbnail?id={fid}&sz=w800" alt="Certificate {idx+1}" loading="lazy" />',
        "iframe_tag": f'<iframe src="https://drive.google.com/file/d/{fid}/preview" width="100%" height="500" allow="autoplay"></iframe>'
    }
    converted_data.append(item)

