out_path = os.path.join(base_dir, 'converted_drive_links.json')

with open(out_path, 'w', encoding='utf-8') as f:
    json.dump(converted_data, f, indent=2)

print(f"Successfully processed and saved {len(converted_data)} Google Drive certificate URLs to {out_path}")
